static int hw_transmit(struct sg2000_eth_priv_s *priv,
                       const uint8_t *data, int len)
{
  unsigned int idx = priv->tx_cur;
  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
  irqstate_t flags;
  uint32_t csr5_before;
  uint32_t csr6;

  /* Check if the ring is full */

  if (desc->des0 & DESC_OWN)
    {
      return -EBUSY;
    }

  /* Diagnostic: snapshot CSR5/CSR6 before TX submission */

  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);

  /* Copy data to DMA TX buffer */

  memcpy(priv->tx_buf[idx], data, len);

  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];

  /* Set OWN on des0.  FS | LS | IC | len on des1.
   * Preserve TER (END_RING) bit in des1 if it was set during init.
   */

  desc->des1 = (uint32_t)len | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
               (desc->des1 & TX_DESC_TER);
  desc->des0 = DESC_OWN;

  /* Diagnostic: dump TX descriptor and DMA state before doorbell */

  syslog(LOG_INFO,
         "sg2000_eth: TX idx=%u len=%d\n"
         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
         " TX_BASE=0x%08" PRIX32 " RX_BASE=0x%08" PRIX32 "\n"
         "  data[0..13]: %02x %02x %02x %02x %02x %02x"
         " %02x %02x %02x %02x %02x %02x %02x %02x\n",
         idx, len,
         desc->des0, desc->des1, desc->des2, desc->des3,
         csr5_before, csr6,
         getreg32(priv->gmac_base + DMA_TX_BASE_ADDR),
         getreg32(priv->gmac_base + DMA_RCV_BASE_ADDR),
         data[0], data[1], data[2], data[3], data[4], data[5],
         data[6], data[7], data[8], data[9], data[10], data[11],
         data[12], data[13]);

  flags = up_irq_save();
  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);

  /* Memory barrier: ensure descriptor is visible to DMA engine */

  __asm__ volatile ("fence w,w" ::: "memory");

  tx_doorbell(priv);

  /* Verify DMA operation: poll descriptor OWN bit with timeout.
   * If DMA clears OWN, TX is working.  If OWN stays set, DMA is stuck.
   */

  {
    int timeout = 10000;
    while ((desc->des0 & DESC_OWN) && --timeout > 0)
      {
        up_udelay(10);
      }

    syslog(LOG_INFO,
           "sg2000_eth: TX complete check: OWN=%s timeout=%d "
           "CSR5=0x%08" PRIX32 "\n",
           (desc->des0 & DESC_OWN) ? "STILL_SET(DMA_STUCK)" : "CLEARED(OK)",
           10000 - timeout,
           getreg32(priv->gmac_base + DMA_STATUS));
  }

  up_irq_restore(flags);

  return 0;
